import Link from "next/link";
import Image from "next/image";

export default function Header() {
  return (
    <header
      className="bg-white px-6 py-3 flex items-center justify-between"
      style={{ borderBottom: "1px solid #C9B99A" }}
    >
      <Link href="/" className="flex items-center gap-2">
        <Image src="/logo.svg" alt="TailleurConnect" width={36} height={36} />
        <span className="text-lg font-bold" style={{ color: "#2D6A4F" }}>
          TailleurConnect
        </span>
      </Link>
      <nav className="flex items-center gap-4">
        <Link href="/auth" className="text-sm" style={{ color: "#4A5568" }}>
          Connexion
        </Link>
        <Link
          href="/auth"
          className="px-4 py-2 rounded-md text-sm font-medium text-white"
          style={{ backgroundColor: "#2D6A4F" }}
        >
          S'inscrire
        </Link>
      </nav>
    </header>
  );
}