import Header from "@/components/shared/Header";
import Button from "@/components/ui/Button";
import Card from "@/components/ui/Card";
import Link from "next/link";
import Image from "next/image";
import { MapPin, Star, Eye, Package, MessageSquare } from "lucide-react";

const couturiersPopulaires = [
  { id: 1, nom: "Sophie Couture", ville: "Cotonou", note: 4.9 },
  { id: 2, nom: "Atelier du Style", ville: "Cotonou", note: 4.9 },
  { id: 3, nom: "Mode & Chic", ville: "Abomey-Calavi", note: 4.4 },
];

const fonctionnalites = [
  { icon: <Eye size={26} className="text-pierre-dark" />, label: "Consultation Facile" },
  { icon: <Package size={26} className="text-pierre-dark" />, label: "Commande Personnalisée" },
  { icon: <MessageSquare size={26} className="text-emeraude" />, label: "Suivi de Commande" },
];

export default function HomePage() {
  return (
    <div className="min-h-screen" style={{ backgroundColor: "#F5EFE6" }}>
      <Header />

      {/* Hero avec ton image */}
      <section className="relative h-64 overflow-hidden">
        <Image
          src="/hero.jpg"
          alt="Couture sur mesure"
          fill
          className="object-cover"
          priority
        />
        <div className="absolute inset-0 bg-black/50 flex flex-col items-center justify-center text-center px-4">
          <h1 className="text-3xl md:text-4xl font-bold text-white mb-2">
            Couture Sur Mesure
          </h1>
          <p className="text-pierre-light text-lg mb-5">
            Des créations uniques à votre mesure.
          </p>
          <Link href="/auth">
            <button
              className="px-6 py-2 rounded-md font-medium text-white text-sm"
              style={{ backgroundColor: "#2D6A4F" }}
            >
              Découvrez Nos Couturiers
            </button>
          </Link>
        </div>
      </section>

      {/* Fonctionnalités */}
      <section className="py-10 px-6 text-center border-b border-pierre">
        <h2 className="text-xl font-bold mb-8" style={{ color: "#4A5568" }}>
          Trouvez Votre Couturier Idéal
        </h2>
        <div className="flex justify-center gap-16 flex-wrap">
          {fonctionnalites.map((f, i) => (
            <div key={i} className="flex flex-col items-center gap-2">
              <div
                className="w-14 h-14 rounded-full flex items-center justify-center shadow"
                style={{ backgroundColor: "#F5EFE6", border: "1px solid #C9B99A" }}
              >
                {f.icon}
              </div>
              <span className="text-sm font-medium" style={{ color: "#4A5568" }}>
                {f.label}
              </span>
            </div>
          ))}
        </div>
      </section>

      {/* Couturiers Populaires */}
      <section className="py-10 px-6 max-w-5xl mx-auto">
        <h2 className="text-xl font-bold text-center mb-8" style={{ color: "#4A5568" }}>
          Couturiers Populaires
        </h2>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
          {couturiersPopulaires.map((c) => (
            <div
              key={c.id}
              className="bg-white rounded-xl shadow-sm overflow-hidden"
              style={{ border: "1px solid #C9B99A" }}
            >
              {/* Placeholder photo couturier */}
              <div
                className="w-full h-40 flex items-center justify-center text-5xl font-bold text-white"
                style={{ backgroundColor: "#A08060" }}
              >
                {c.nom[0]}
              </div>
              <div className="p-3">
                <div className="flex items-center justify-between">
                  <span className="font-semibold text-sm" style={{ color: "#4A5568" }}>
                    {c.nom}
                  </span>
                  <span className="flex items-center gap-1 text-sm text-yellow-500 font-medium">
                    <Star size={13} fill="currentColor" />
                    {c.note}
                  </span>
                </div>
                <div className="flex items-center gap-1 text-xs mt-1" style={{ color: "#718096" }}>
                  <MapPin size={12} />
                  {c.ville}
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Footer */}
      <footer
        className="text-center py-6 text-sm border-t mt-8"
        style={{ color: "#718096", borderColor: "#C9B99A" }}
      >
        © 2026 TailleurConnect — Tous droits réservés
      </footer>
    </div>
  );
}